from __future__ import annotations

from datetime import date
import polars as pl
from src.backtest.strategy import MarketView, Signal, Strategy


class LiquidityEqualWeighting(Strategy):
    rationale = (
        "This strategy exploits the phenomenon where smaller-cap stocks often exhibit "
        "higher returns due to liquidity premiums. By screening for liquid stocks and then "
        "applying equal weighting across a selected subset, we aim to balance risk while "
        "capturing potential higher returns from less liquid but promising smaller-cap firms."
    )

    def __init__(self, window: int = 20, min_liquidity: float = 1e6) -> None:
        self._window = window
        self._min_liquidity = min_liquidity

    def generate(self, view: MarketView) -> Signal:
        stamp = _latest_visible(view)
        history = view.history(lookback=self._window)

        if history.is_empty():
            return Signal(information_available_at=stamp, weights={})

        liquidity_scores = (
            history.with_columns(
                pl.col("volume").rolling_sum(window_size=self._window).alias("liquidity_score")
            )
            .filter(pl.col("liquidity_score") >= self._min_liquidity)
            .group_by("symbol")
            .agg(pl.count().alias("count"))
            .sort("count", descending=True)
        )

        symbols = liquidity_scores.select("symbol").to_series().to_list()[:100]

        if not symbols:
            return Signal(information_available_at=stamp, weights={})

        weight = 1.0 / len(symbols)
        return Signal(
            information_available_at=stamp,
            weights={s: weight for s in symbols},
        )


def _latest_visible(view: MarketView) -> date:
    visible = view.history()
    if visible.is_empty():
        return date(1900, 1, 1)
    newest = visible["session_date"].max()
    assert isinstance(newest, date)
    return newest
